```html
<!DOCTYPE html>
<html>
<head>
  <title>DOM básico</title>
</head>
<body>
  <p id="msg">Hola</p>
  <button id="btn">Cambiar</button>

  <script>
    const btn = document.getElementById('btn');
    const msg = document.getElementById('msg');

    btn.addEventListener('click', () => {
      msg.textContent = '¡Mundo!';
    });
  </script>
</body>
</html>
```
